// edits. A row after the registered history is accepted only when it has a
// compatible_with set and this code registers each migration that the set
// names (ST-SUP-RC01-OC28).
func checkLedger(applied, registered []Migration) error {
	known := map[string]bool{}
	for _, m := range registered {
		known[m.Name] = true
	}
	for i, row := range applied {
		if i >= len(registered) {
			if !row.Step {
				return &ledgerRefusal{remedy: laterRemedy, text: fmt.Sprintf("the ledger row %d names the migration %q, which is after the last migration %q of this release and is not a schema step: "+
					"a later release applied it. Deploy that release or a later one; the job changed nothing (ST-SUP-RC01-OC28)", i+1, row.Name, lastName(registered))}
			}
			for _, name := range row.CompatibleWith {
				if !known[name] {
					return &ledgerRefusal{remedy: laterRemedy, text: fmt.Sprintf("the ledger row %d names the schema step %q of a later release, which needs the migration %q, and this release does not hold it: "+
						"deploy the release of the step or a later one; the job changed nothing (ST-SUP-RC01-OC28)", i+1, row.Name, name)}
				}
			}
			continue
		}
		if row.Name != registered[i].Name {
			return &ledgerRefusal{remedy: historyRemedy, text: fmt.Sprintf("the ledger row %d names the migration %q, and this release has the migration %q at that place: "+
				"the database ran the migrations of another history, such as the build of a branch whose schema steps took other numbers before the merge. "+
				"The body of an applied migration never changes, and nothing removes a ledger row. Run this release on a database that ran only releases of its own history: "+
				"restore a backup made before the other build, or make the database again, such as a new preview database; the job changed nothing (ST-SUP-RC01-OC51)",
				i+1, row.Name, registered[i].Name)}
		}
		if row.Digest != registered[i].Digest && !earlierDigest(registered[i], row.Digest) {
			return &digestRefusal{text: fmt.Sprintf("the ledger row of the migration %q holds the digest %q, and this release registers the digest %q for its body: "+
				"the body of an applied migration never changes, so a change comes as a new schema step. Deploy the release that applied it, "+
				"or a release that keeps its body and brings the change in a new schema step; the job changed nothing, and nothing repairs the digest (ST-SUP-RC01-OC51)",
				row.Name, row.Digest, registered[i].Digest)}
		}
	}
	return nil
}

// lastName gives the name of the last migration of registered, or none.
func lastName(registered []Migration) string {
	if len(registered) == 0 {
		return "(none)"
	}
	return registered[len(registered)-1].Name
}

// ledgerRefusal is the refusal of a ledger that is not the history of this
// release, other than a changed body: a row of another migration at the
// place of one of this release, or a row after this release that it cannot
// accept. Its text names the row, the migration and the remedy, and no part
// of a body, so the migration job may log it (Refusal). It matches
// ErrMigrationLedger. The failure record of the process names its fault
// class, the ledger and its remedy, fixed texts with no name of a row.
type ledgerRefusal struct{ text, remedy string }

// The remedies of a ledger that is not the history of this release.
const (
	historyRemedy = "the database ran the migrations of another history, such as a branch build: restore a backup made before it, or make the database again; the line migrate: the step is refused names the row and the migration"
	laterRemedy   = "a later release applied a migration that this release cannot accept: deploy that release or a later one; the line migrate: the step is refused names the row and the migration"
)

func (r *ledgerRefusal) Error() string        { return r.text }
func (r *ledgerRefusal) Refusal() string      { return r.text }
func (r *ledgerRefusal) Is(target error) bool { return target == ErrMigrationLedger }
func (r *ledgerRefusal) FaultClass() string   { return "migration_ledger.history" }
func (r *ledgerRefusal) FaultObject() string  { return "stego_schema.migrations" }
func (r *ledgerRefusal) FaultRemedy() string  { return r.remedy }
func (r *ledgerRefusal) CauseClass() string   { return refusedCause }

// refusedCause is the cause class of the failure record of a step that a
// check of the ledger or of a contract step refused: the job changed
// nothing, and the remedy says what to do (walkthrough 21, U-F).
const refusedCause = "refused"

// earlierDigest tells whether digest is one of the earlier digests of m.
func earlierDigest(m Migration, digest string) bool {
	for _, d := range m.Earlier {
		if d == digest {
			return true
		}
	}
	return false
}

// digestRefusal is the refusal of a ledger row whose digest is not the body
// digest of the registered migration of the same name: its text names the
// migration, the two digests and the remedy, and no part of a body, so the
// migration job may log it (Refusal). It matches ErrMigrationLedger. The
// failure record of the process names its fault class, the ledger, its
// remedy and the cause class refused, fixed texts with no name of a row
// (walkthrough 21, U-F).
type digestRefusal struct{ text string }

// digestRemedy is the remedy of a ledger row whose digest is not the body
// digest of this release.
const digestRemedy = "the body of an applied migration changed: deploy the release that applied it, or a release that keeps its body and brings the change in a new schema step; the line migrate: the step is refused names the migration and the two digests"

func (r *digestRefusal) Error() string        { return r.text }
func (r *digestRefusal) Refusal() string      { return r.text }
func (r *digestRefusal) Is(target error) bool { return target == ErrMigrationLedger }
func (r *digestRefusal) FaultClass() string   { return "migration_ledger.digest" }
func (r *digestRefusal) FaultObject() string  { return "stego_schema.migrations" }
func (r *digestRefusal) FaultRemedy() string  { return digestRemedy }
func (r *digestRefusal) CauseClass() string   { return refusedCause }

// applyPending applies the migrations after the recorded history, one
// transaction each, at read committed whatever the default isolation of the
// database is, so each statement takes its snapshot after the ledger lock is
// granted: it takes the ledger lock, reads the ledger again,
// refuses a ledger that is not a prefix of the registered history, and
// applies the next migration with its ledger row. A migration that another
// job applied in the meantime is not applied again. A migration of a schema
// step runs under the limits of a step (stepTimeouts), and when it waits too
// long for a lock it runs again after a pause, at most stepAttempts times
// (ST-SUP-RC01-OC22). The build of an index of a step runs outside a
// transaction (applyIndex).
func applyPending(ctx context.Context, db Database, ordered []Migration) error {
	if err := refreshSealCheckpoints(ctx, db, ordered); err != nil {
		return err
	}
	tries := 0
	for {
		done := false
		var index *Migration
		err := inTransaction(ctx, db, &sql.TxOptions{Isolation: sql.LevelReadCommitted}, func(tx *sql.Tx) error {
			if err := lockLedger(ctx, tx); err != nil {
				return err
			}
			applied, err := appliedMigrations(ctx, tx)
			if err != nil {
				return err
			}
			if err := checkLedger(applied, ordered); err != nil {
				return err
			}
			if err := refreshMarker(ctx, tx); err != nil {
				return err
			}
			if len(applied) >= len(ordered) {
				done = true
				// The seal checkpoints run once more at the end of each job, so a
				// database whose migrations an earlier release applied gets the
				// functions of this release (RegisterSealCheckpoints).
				if sealCheckpoints == "" {
					return nil
				}
				if _, err := tx.ExecContext(ctx, "SELECT pg_catalog.set_config('lock_timeout', $1, true), pg_catalog.set_config('statement_timeout', $2, true)", stepLockTimeout, stepStatementTimeout); err != nil {
					return err
				}
				if err := applySealCheckpoints(ctx, tx); err != nil {
					return fmt.Errorf("the seal checkpoints: %w", err)
				}
				return nil
			}
			m := ordered[len(applied)]
			if m.Index != "" || m.Contract != nil {
				index = &m
				return nil
			}
			if m.Step {
				if err := stepTimeouts(ctx, tx, m); err != nil {
					return err
				}
			}
			if err := m.Func(ctx, tx); err != nil {
				return fmt.Errorf("migration %s: %w", m.Name, err)
			}
			if err := applySealCheckpoints(ctx, tx); err != nil {
				return fmt.Errorf("migration %s: the seal checkpoints: %w", m.Name, err)
			}
			return recordMigration(ctx, tx, m)
		})
		if err == nil && index != nil && index.Contract != nil {
			err = applyContract(ctx, db, ordered, *index)
		} else if err == nil && index != nil {
			err = applyIndex(ctx, db, ordered, *index)
		}
		if err != nil {
			tries++
			if !lockTimedOut(err) || tries >= stepAttempts {
				return err
			}
			if err := pause(ctx, tries); err != nil {
				return err
			}
			continue
		}
		tries = 0
		if done {
			return nil
		}
	}
}

// refreshSealCheckpoints runs the seal checkpoints once at the start of the
// job, in a transaction of its own under the ledger lock, after the ledger
// check and the marker, and before the first pending migration: so the check
// of a seal contract step, which runs before any migration of this job, reads
// the functions of this release also on a database where an earlier release
// applied the expand step (security review of PR #472, L1). On a lock timeout
// it tries again as applyPending does.
func refreshSealCheckpoints(ctx context.Context, db Database, ordered []Migration) error {
	if sealCheckpoints == "" {
		return nil
	}
	for tries := 1; ; tries++ {
		err := inTransaction(ctx, db, &sql.TxOptions{Isolation: sql.LevelReadCommitted}, func(tx *sql.Tx) error {
			if err := lockLedger(ctx, tx); err != nil {
				return err
			}
			applied, err := appliedMigrations(ctx, tx)
			if err != nil {
				return err
			}
			if err := checkLedger(applied, ordered); err != nil {
				return err
			}
			if err := refreshMarker(ctx, tx); err != nil {
				return err
			}
			if _, err := tx.ExecContext(ctx, "SELECT pg_catalog.set_config('lock_timeout', $1, true), pg_catalog.set_config('statement_timeout', $2, true)", stepLockTimeout, stepStatementTimeout); err != nil {
				return err
			}
			if err := applySealCheckpoints(ctx, tx); err != nil {
				return fmt.Errorf("the seal checkpoints: %w", err)
			}
			return nil
		})
		if err == nil || !lockTimedOut(err) || tries >= stepAttempts {
			return err
		}
		if err := pause(ctx, tries); err != nil {
			return err
		}
	}
}

// stepTimeouts sets, in the transaction of a migration of a schema step and
// after the ledger lock, the lock timeout of a step and the statement timeout
// of the migration (ST-SUP-RC01-OC22).
func stepTimeouts(ctx context.Context, tx *sql.Tx, m Migration) error {
	_, err := tx.ExecContext(ctx, "SELECT pg_catalog.set_config('lock_timeout', $1, true), pg_catalog.set_config('statement_timeout', $2, true)", stepLockTimeout, m.StatementTimeout)
	return err
}

// lockTimedOut tells whether err ends a wait for a lock at the lock timeout:
// SQLSTATE 55P03, lock_not_available.
func lockTimedOut(err error) bool {
	var state interface{ SQLState() string }
	return errors.As(err, &state) && state.SQLState() == "55P03"
}

// pause waits before the next attempt of a migration that waited too long for
// a lock: a time that doubles with each attempt from 100ms to at most 5s, of
// which a random part, so that two jobs do not try again at once.
func pause(ctx context.Context, attempt int) error {
	wait := 100 * time.Millisecond << min(attempt-1, 6)
	wait = min(wait, 5*time.Second)
	wait = wait/2 + rand.N(wait/2+1)
	timer := time.NewTimer(wait)
	defer timer.Stop()
	select {
	case <-ctx.Done():
		return ctx.Err()
	case <-timer.C:
		return nil
	}
}

// ledgerLockKey is the key of the ledger lock: lockLedger takes it for a
// transaction, and applyIndex for its session.
const ledgerLockKey = "1937007983,1935894637"

// applyIndex builds the index of the migration m of a schema step on a table
// with rows (ST-SUP-RC01-OC38). It holds the ledger lock for its session, on
// one connection, and no transaction is open on it while the index builds, so
// CREATE INDEX CONCURRENTLY waits for no transaction of its own job. It reads
// the ledger again, and builds nothing when another job has applied m. It
// first drops an invalid index of the same name, which a build that stopped
// part way left, by DROP INDEX CONCURRENTLY, and when the build fails it drops
// the invalid index that the build left at once, so that no half-built index
// stays (decision on finding F9); when that drop fails, it tries again
// (dropAfterFailure). The build waits for each transaction older than its
// snapshots, so it runs with no lock timeout and under the statement timeout
// of m; the drops run under the lock timeout of a step. It writes the ledger
// row only after the build succeeds and the index has the definition of m
// (indexBuilt).
func applyIndex(ctx context.Context, db Database, ordered []Migration, m Migration) error {
	conn, release, err := sessionOf(ctx, db)
	if err != nil {
		return err
	}
	defer release()
	if _, err := conn.ExecContext(ctx, "SELECT pg_catalog.pg_advisory_lock("+ledgerLockKey+")"); err != nil {
		return err
	}
	defer func() {
		_, _ = conn.ExecContext(context.WithoutCancel(ctx), "SELECT pg_catalog.pg_advisory_unlock("+ledgerLockKey+")")
	}()
	position := -1
	for i := range ordered {
		if ordered[i].Name == m.Name {
			position = i
		}
	}
	pending := func(tx *sql.Tx) (bool, error) {
		applied, err := appliedMigrations(ctx, tx)
		if err != nil {
			return false, err
		}
		if err := checkLedger(applied, ordered); err != nil {
			return false, err
		}
		return len(applied) == position, nil
	}
	next := false
	if err := inTransaction(ctx, conn, &sql.TxOptions{Isolation: sql.LevelReadCommitted, ReadOnly: true}, func(tx *sql.Tx) error {
		var err error
		next, err = pending(tx)
		return err
	}); err != nil || !next {
		return err
	}
	if _, err := conn.ExecContext(ctx, "SELECT pg_catalog.set_config('lock_timeout', $1, false), pg_catalog.set_config('statement_timeout', $2, false)", stepLockTimeout, m.StatementTimeout); err != nil {
		return err
	}
	defer func() {
		_, _ = conn.ExecContext(context.WithoutCancel(ctx), "RESET lock_timeout; RESET statement_timeout")
	}()
	if err := dropInvalid(ctx, conn, m.Index); err != nil {
		return fmt.Errorf("migration %s: %w", m.Name, err)
	}
	if _, err := conn.ExecContext(ctx, "SELECT pg_catalog.set_config('lock_timeout', '0', false)"); err != nil {
		return err
	}
	if _, err := conn.ExecContext(ctx, m.Body); err != nil {
		build := fmt.Errorf("migration %s: %w", m.Name, err)
		// Two rows that hold one value of a unique key stop the build of its index with a refusal that names the
		// migration, the index and the table, and no row value (ST-SUP-RC01-OC38, ST-GEN-Q48).
		build = duplicateRefusal(m, err, build)
		if err := dropAfterFailure(context.WithoutCancel(ctx), conn, m.Index); err != nil {
			return fmt.Errorf("%w; %v", build, err)
		}
		return build
	}
	if err := indexBuilt(ctx, conn, m.Index, m.Definition); err != nil {
		return fmt.Errorf("migration %s: %w", m.Name, err)
	}
	return inTransaction(ctx, conn, &sql.TxOptions{Isolation: sql.LevelReadCommitted}, func(tx *sql.Tx) error {
		next, err := pending(tx)
		if err != nil || !next {
			return err
		}
		return recordMigration(ctx, tx, m)
	})
}

// applyContract runs the contract migration m of a schema change
// (ST-SUP-RC01-OC24, ST-SUP-RC01-OC39). It holds the ledger lock for its
// session on one connection, reads the ledger again and runs nothing when
// another job has applied m. It first checks the step in its own transaction
// (checkContract), which runs the seal checkpoints first for the step of a
// seal (applySealCheckpoints), and refuses with the change and the count of rows left,
// changes no schema and writes no ledger row when the check fails. Then it
// runs each statement in its own short transaction under the lock timeout and
// the statement timeout of a step, again after a pause when the lock wait ends
// at the timeout, at most stepAttempts times; the statement that drops the
// sync trigger checks the step again in its transaction, and drops the
// completeness CHECK and the old column in that same transaction, so no write
// of the release before can change the old column alone after the trigger is
// gone (security review of PR #316, H1). It writes the ledger row last.
func applyContract(ctx context.Context, db Database, ordered []Migration, m Migration) error {
	conn, release, err := sessionOf(ctx, db)
	if err != nil {
		return err
	}
	defer release()
	if _, err := conn.ExecContext(ctx, "SELECT pg_catalog.pg_advisory_lock("+ledgerLockKey+")"); err != nil {
		return err
	}
	defer func() {
		_, _ = conn.ExecContext(context.WithoutCancel(ctx), "SELECT pg_catalog.pg_advisory_unlock("+ledgerLockKey+")")
	}()
	position := -1
	for i := range ordered {
		if ordered[i].Name == m.Name {
			position = i
		}
	}
	pending := func(tx *sql.Tx) (bool, error) {
		applied, err := appliedMigrations(ctx, tx)
		if err != nil {
			return false, err
		}
		if err := checkLedger(applied, ordered); err != nil {
			return false, err
		}
		return len(applied) == position, nil
	}
	next := false
	if err := inTransaction(ctx, conn, &sql.TxOptions{Isolation: sql.LevelReadCommitted, ReadOnly: true}, func(tx *sql.Tx) error {
		var err error
		next, err = pending(tx)
		return err
	}); err != nil || !next {
		return err
	}
	c := *m.Contract
	if err := inTransaction(ctx, conn, &sql.TxOptions{Isolation: sql.LevelReadCommitted}, func(tx *sql.Tx) error {
		if err := stepTimeouts(ctx, tx, m); err != nil {
			return err
		}
		// The check of a seal reads the functions of this release: the check transaction runs the seal
		// checkpoints itself, and does not depend on the run at the start of the job and on the ledger lock
		// (security review of PR #472, second review, L1).
		if c.Seal {
			if err := applySealCheckpoints(ctx, tx); err != nil {
				return fmt.Errorf("the seal checkpoints: %w", err)
			}
		}
		return checkContract(ctx, tx, c)
	}); err != nil {
		return fmt.Errorf("migration %s: %w", m.Name, err)
	}
	for _, s := range c.Statements {
		if err := contractStatementRun(ctx, conn, m, c, s); err != nil {
			return fmt.Errorf("migration %s: %w", m.Name, err)
		}
	}
	return inTransaction(ctx, conn, &sql.TxOptions{Isolation: sql.LevelReadCommitted}, func(tx *sql.Tx) error {
		next, err := pending(tx)
		if err != nil || !next {
			return err
		}
		return recordMigration(ctx, tx, m)
	})
}

// contractStatementRun runs one statement s of the contract step c of the
// migration m, with its statements Also, in its own transaction, when its
// query When gives that it still has to run, after the check of the step when
// it is a Guard, under the lock
// timeout of a step and the statement timeout of m, or the long one; it runs
// it again after a pause when the lock wait ends at the timeout, at most
// stepAttempts times. The last failure is wrapped as text, so the caller does
// not take it for one more lock wait to retry.
func contractStatementRun(ctx context.Context, conn *sql.Conn, m Migration, c ContractStep, s ContractStatement) error {
	timeout := m.StatementTimeout
	if s.Long {
		timeout = longStatementTimeout
	}
	for attempt := 1; ; attempt++ {
		err := inTransaction(ctx, conn, &sql.TxOptions{Isolation: sql.LevelReadCommitted}, func(tx *sql.Tx) error {
			if _, err := tx.ExecContext(ctx, "SELECT pg_catalog.set_config('lock_timeout', $1, true), pg_catalog.set_config('statement_timeout', $2, true)", stepLockTimeout, timeout); err != nil {
				return err
			}
			if s.When != "" {
				var run bool
				if err := tx.QueryRowContext(ctx, s.When).Scan(&run); err != nil {
					return err
				}
				if !run {
					return nil
				}
			}
			if s.Guard && (c.Drop || c.Seal) {
				// A statement of a drop or a seal takes the lock of its table first and checks the step after it, in
				// the same transaction: a process of the release before that reports itself after the check can no
				// longer write the table before the statement commits (security review of PR #423, M1 and I2; of PR
				// #443, M1).
				table := quoteIdentifier(c.Schema) + "." + quoteIdentifier(c.Table)
				var there bool
				if err := tx.QueryRowContext(ctx, "SELECT pg_catalog.to_regclass($1) IS NOT NULL", table).Scan(&there); err != nil {
					return err
				}
				if there {
					if _, err := tx.ExecContext(ctx, "LOCK TABLE "+table+" IN ACCESS EXCLUSIVE MODE"); err != nil {
						return err
					}
				}
			}
			if s.Guard {
				if err := checkContract(ctx, tx, c); err != nil {
					return err
				}
			}
			for _, statement := range append([]string{s.SQL}, s.Also...) {
				if _, err := tx.ExecContext(ctx, statement); err != nil {
					return err
				}
			}
			return nil
		})
		if err == nil {
			return nil
		}
		if c.Seal && s.Long && violatesCheck(err) && strings.Contains(s.SQL, "VALIDATE CONSTRAINT "+quoteIdentifier(c.Check)) {
			// The VALIDATE of the completeness CHECK, Check, reads every row, also a row of a tenant that the tenant
			// list does not hold, which the seal job does not seal (security review of PR #443, I4; re-review N5).
			return &contractRefusal{text: fmt.Sprintf("the contract step of the schema change %s waits for its seal: a row has a clear value and no sealed value, and the seal job has sealed each row of the listed tenants, so the row is of a tenant that the tenant list stego_tenants does not hold; provision that tenant and run the release of the expand step %s until the seal job completes a pass, or remove the rows of that tenant", c.Change, c.Expand), wait: sealWait}
		}
		if !lockTimedOut(err) {
			return err
		}
		if attempt >= stepAttempts {
			return fmt.Errorf("%s waited for its lock %d times, and the last wait ended with: %v", s.SQL, attempt, err)
		}
		if err := pause(ctx, attempt); err != nil {
			return err
		}
	}
}

// violatesCheck tells whether err is a row that breaks a CHECK: SQLSTATE 23514, check_violation.
func violatesCheck(err error) bool {
	var state interface{ SQLState() string }
	return errors.As(err, &state) && state.SQLState() == "23514"
}

// duplicateRefusal gives the refusal of the index migration m whose build
// failed with err: for a unique violation (SQLSTATE 23505), a refusal whose
// text names the migration, the index and its table, says that two or more
// rows hold one value of its key and what to do, and holds no row value, so
// the migration job may log it; for each other error, build as it is.
func duplicateRefusal(m Migration, err, build error) error {
	var coded interface{ SQLState() string }
	if !errors.As(err, &coded) || coded.SQLState() != "23505" {
		return build
	}
	return &keyRefusal{text: fmt.Sprintf("the migration %s does not build the unique index %s of %s: two or more rows of the table hold one value of its key; correct or remove those rows, then run the migration job again (ST-SUP-RC01-OC38)",
		m.Name, m.Index, indexTable(m.Definition)), err: err, key: uniqueKeyFault, name: m.Index}
}

// indexTable gives the table of an index from its definition as
// pg_get_indexdef writes it, CREATE [UNIQUE] INDEX <name> ON <table> USING
// ..., or "its table" when the definition does not have that form.
func indexTable(definition string) string {
	words := strings.Fields(definition)
	for i := 0; i+2 < len(words); i++ {
		if strings.EqualFold(words[i], "on") && strings.EqualFold(words[i+2], "using") {
			return words[i+1]
		}
	}
	return "its table"
}

// keyRefusal is the refusal of a validate migration whose foreign key a row
// breaks, or of an index migration whose unique key two rows break: its text
// names the step, the table and the key and no row value, so the migration
// job may log it (Refusal). It wraps the database error, whose SQLSTATE 23503
// or 23505 the job keeps. The failure record of the process names the key as
// its fault class, the constraint or the index as its object, and the remedy:
// fixed texts with no row value (walkthrough 23, D-f).
type keyRefusal struct {
	text string
	err  error
	key  keyFault
	name string
}

// keyFault is the fault class and the remedy of a key refusal.
type keyFault struct{ fault, object, remedy string }

// The faults of a key refusal.
var (
	foreignKeyFault = keyFault{"schema_change.foreign_key_broken", "foreign_key", "a row breaks the foreign key that the step validates: find the rows whose reference names no row of the referenced table, correct or remove them, then run the migration job again; the line migrate: the step is refused names the step, the key and the table"}
	uniqueKeyFault  = keyFault{"schema_change.unique_duplicates", "unique_index", "two or more rows hold one value of the key of the unique index that the migration builds: find them with a GROUP BY of the key columns HAVING count(*) > 1, correct or remove them, then run the migration job again; the line migrate: the step is refused names the migration, the index and the table"}
)

func (r *keyRefusal) Error() string       { return r.text }
func (r *keyRefusal) Refusal() string     { return r.text }
func (r *keyRefusal) Unwrap() error       { return r.err }
func (r *keyRefusal) FaultClass() string  { return r.key.fault }
func (r *keyRefusal) FaultRemedy() string { return r.key.remedy }

// FaultObject gives the name of the constraint or of the index, with no
// schema and no quotes, when it has the form of a name of the generated code,
// else the kind of the key.
func (r *keyRefusal) FaultObject() string {
	name := r.name
	if i := strings.LastIndex(name, "."); i >= 0 {
		name = name[i+1:]
	}
	if name = strings.Trim(name, "\""); faultName(name) {
		return name
	}
	return r.key.object
}

// faultName tells whether name has the form of a name that the failure
// record takes as an object: a lower-case letter, then at most 127 lower-case
// letters, digits, '_' and '.'.
func faultName(name string) bool {
	if len(name) == 0 || len(name) > 128 || name[0] < 'a' || name[0] > 'z' {
		return false
	}
	for i := 1; i < len(name); i++ {
		if c := name[i]; !(c >= 'a' && c <= 'z' || c >= '0' && c <= '9' || c == '_' || c == '.') {
			return false
		}
	}
	return true
}

// contractRefusal is the refusal of a contract step: its text names the
// change, the counts and the labels of the running releases, and no row
// value, so the migration job may log it (Refusal). The failure record of the
// process names what the step waits for as its fault class, the table that
// tells it, the remedy and the cause class refused: fixed texts with no name
// of a change or a row (walkthrough 21, U-F).
type contractRefusal struct {
	text string
	wait contractWait
}

// contractWait is what a contract step waits for: its fault class, the table
// that tells it, and the remedy.
type contractWait struct{ fault, object, remedy string }

// The waits of a contract step.
var (
	sealWait     = contractWait{"schema_change.seal_pending", "stego_schema.seals", "the contract step of a seal waits for a complete pass of the seal job: run the release of the expand step, with its controller, until the seal job completes a pass, then run the migration job again; the line migrate: the step is refused names the change and the state"}
	backfillWait = contractWait{"schema_change.backfill_pending", "stego_schema.backfills", "the contract step waits for the backfill of its change: run the migration job of the release before until the backfill completes, then run the migration job again; the line migrate: the step is refused names the change and the rows left"}
	reportsWait  = contractWait{"schema_change.release_reports", "stego_schema.releases", "the contract step finds no table of the release reports: run the migration job of the release of the expand step first; the line migrate: the step is refused names the change"}
	releaseWait  = contractWait{"schema_change.release_before_running", "stego_schema.releases", "a release before the expand step still runs: stop it, then run the migration job again; the line migrate: the step is refused names the change and the releases"}
)

func (r *contractRefusal) Error() string       { return r.text }
func (r *contractRefusal) Refusal() string     { return r.text }
func (r *contractRefusal) FaultClass() string  { return r.wait.fault }
func (r *contractRefusal) FaultObject() string { return r.wait.object }
func (r *contractRefusal) FaultRemedy() string { return r.wait.remedy }
func (r *contractRefusal) CauseClass() string  { return refusedCause }

// checkContract checks the contract step c in the transaction tx
// (ST-SUP-RC01-OC24): while the sync trigger of the change or the old column
// is there, the backfill row of the change must be complete with no failed
// row, the completeness CHECK of the expand step must be there with its exact
// definition, as inherited, and validated, which proves that no row of any
// tenant has the old column set and the new one empty (decision on
// ST-SUP-Q120 (c); security review of PR #316, L1), and no release that does
// not know the change may run (runningReleases). A refusal gives the rows left
// of each listed tenant. When the trigger and the old column are both gone, a
// run before passed this check and dropped them in one transaction, so the
// check passes and the rerun goes on; when only the trigger is gone, the check
// runs in full again (security review of PR #316, H1). A trigger of the name
// that is disabled, fires only on a replica, or does not run the sync function
// stego_steps.<trigger>() does not copy the writes of the release before, so
// the check refuses it (security review of PR #316, L2); so does a trigger
// whose definition, as pg_get_triggerdef gives it, is not the one that the
// step made, CREATE TRIGGER <trigger> BEFORE INSERT OR UPDATE ON <table> FOR
// EACH ROW EXECUTE FUNCTION stego_steps.<trigger>(), as one that fires only on
// an INSERT, on an UPDATE OF another column, with a WHEN condition, for each
// statement or after the row (security review of PR #320, L1). It reads the
// catalog and the tables of the step with the search path pg_catalog,
// pg_temp, so pg_get_triggerdef names the schema of the sync function
// whatever the search path of the session, and only the operators of
// pg_catalog run in each compare, up to its last read (review of PR #320,
// info; security review of PR #332, INFO-3). When the check passes, it sets
// the search path of tx back for the statements of the step; a refusal or an
// error rolls tx back, and the path with it.
func checkContract(ctx context.Context, tx *sql.Tx, c ContractStep) (err error) {
	table := quoteIdentifier(c.Schema) + "." + quoteIdentifier(c.Table)
	var path string
	if err := tx.QueryRowContext(ctx, "SELECT pg_catalog.current_setting('search_path')").Scan(&path); err != nil {
		return err
	}
	if _, err := tx.ExecContext(ctx, "SELECT pg_catalog.set_config('search_path', 'pg_catalog, pg_temp', true)"); err != nil {
		return err
	}
	defer func() {
		if err == nil {
			_, err = tx.ExecContext(ctx, "SELECT pg_catalog.set_config('search_path', $1, true)", path)
		}
	}()
	if c.Seal {
		return checkSeal(ctx, tx, c, table)
	}
	if c.Drop {
		// A drop has no sync trigger and no backfill: while its old column or table is there, the check refuses
		// while a release that still reads it runs, and when it is gone a run before dropped it. The contract of a
		// relax with the item searchable checks its search index in the same way.
		var there bool
		query := "SELECT pg_catalog.to_regclass($1) IS NOT NULL"
		args := []any{table}
		switch {
		case c.Index != "":
			args = []any{quoteIdentifier(c.Schema) + "." + quoteIdentifier(c.Index)}
		case c.From != "":
			query = "SELECT EXISTS (SELECT 1 FROM pg_catalog.pg_attribute a WHERE a.attrelid = pg_catalog.to_regclass($1) AND a.attname = $2 AND a.attnum > 0 AND NOT a.attisdropped)"
			args = append(args, c.From)
		}
		if err := tx.QueryRowContext(ctx, query, args...).Scan(&there); err != nil {
			return err
		}
		if !there {
			return nil
		}
		return runningReleases(ctx, tx, c)
	}
	var trigger, syncing, column bool
	if err := tx.QueryRowContext(ctx, "SELECT EXISTS (SELECT 1 FROM pg_catalog.pg_trigger t WHERE t.tgrelid = pg_catalog.to_regclass($1) AND t.tgname = $2 AND NOT t.tgisinternal), EXISTS (SELECT 1 FROM pg_catalog.pg_trigger t JOIN pg_catalog.pg_proc p ON p.oid = t.tgfoid JOIN pg_catalog.pg_namespace n ON n.oid = p.pronamespace JOIN pg_catalog.pg_class r ON r.oid = t.tgrelid JOIN pg_catalog.pg_namespace rn ON rn.oid = r.relnamespace WHERE t.tgrelid = pg_catalog.to_regclass($1) AND t.tgname = $2 AND NOT t.tgisinternal AND t.tgenabled IN ('O', 'A') AND n.nspname = 'stego_steps' AND p.proname = $2 AND p.pronargs = 0 AND pg_catalog.pg_get_triggerdef(t.oid) = 'CREATE TRIGGER ' || pg_catalog.quote_ident($2) || ' BEFORE INSERT OR UPDATE ON ' || pg_catalog.quote_ident(rn.nspname) || '.' || pg_catalog.quote_ident(r.relname) || ' FOR EACH ROW EXECUTE FUNCTION stego_steps.' || pg_catalog.quote_ident($2) || '()'), EXISTS (SELECT 1 FROM pg_catalog.pg_attribute a WHERE a.attrelid = pg_catalog.to_regclass($1) AND a.attname = $3 AND a.attnum > 0 AND NOT a.attisdropped)", table, c.Trigger, c.From).Scan(&trigger, &syncing, &column); err != nil {
		return err
	}
	if !trigger && !column {
		return nil
	}
	var complete bool
	var failed int64
	err = tx.QueryRowContext(ctx, "SELECT b.completed_at IS NOT NULL, b.failed_rows FROM stego_schema.backfills b WHERE b.change_id = $1", c.Change).Scan(&complete, &failed)
	found := err == nil
	if err != nil && !errors.Is(err, sql.ErrNoRows) {
		return err
	}
	var definition string
	var noInherit, validated bool
	err = tx.QueryRowContext(ctx, "SELECT pg_catalog.pg_get_constraintdef(k.oid), k.contype <> 'c' OR k.connoinherit, k.convalidated FROM pg_catalog.pg_constraint k WHERE k.conrelid = pg_catalog.to_regclass($1) AND k.conname = $2", table, c.Check).Scan(&definition, &noInherit, &validated)
	present := err == nil
	if err != nil && !errors.Is(err, sql.ErrNoRows) {
		return err
	}
	exact := present && !noInherit && strings.TrimSuffix(definition, " NOT VALID") == c.Definition
	state := ""
	switch {
	case trigger && !syncing:
		state = "the sync trigger " + c.Trigger + " is disabled or does not run its sync function before each write of a row"
	case !found:
		state = "the backfill has no checkpoint row"
	case failed > 0:
		state = fmt.Sprintf("the backfill has %d failed rows", failed)
	case !complete:
		state = "the backfill is not complete"
	case !present:
		state = "the completeness CHECK " + c.Check + " is not there"
	case !exact:
		state = "the constraint " + c.Check + " is not the completeness CHECK of the change"
	case !validated:
		state = "the completeness CHECK " + c.Check + " is not validated"
	}
	if state != "" {
		left, err := rowsLeft(ctx, tx, c)
		count := "unknown"
		if err == nil {
			count = fmt.Sprint(left)
		}
		return &contractRefusal{text: fmt.Sprintf("the contract step of the schema change %s waits for its backfill: %s; rows of the listed tenants with the old column set and the new one empty: %s; run the migration job of the release before until the backfill completes", c.Change, state, count), wait: backfillWait}
	}
	// A last count of the rows with the old column set and the new one empty: a write that the completeness CHECK
	// let through, as a value that does not convert with no fill value, would lose its value when the old column
	// goes (security review of PR #335, L5, orchestrator under the owner's delegation, 2026-11-14).
	left, err := rowsLeft(ctx, tx, c)
	if err != nil {
		return err
	}
	if left > 0 {
		return &contractRefusal{text: fmt.Sprintf("the contract step of the schema change %s waits for its backfill: rows of the listed tenants with the old column set and the new one empty: %d; run the migration job of the release before until the backfill completes", c.Change, left), wait: backfillWait}
	}
	return runningReleases(ctx, tx, c)
}

// checkSeal checks the contract step c of a seal in tx (ST-SUP-RC01-OC50):
// while the clear column is there, the seal checkpoint of the change must
// hold a completed pass, no release before the expand migration may have
// reported itself within its window after the start of that pass, since such a
// release writes the clear column alone and its write would be lost with the
// column (ST-SUP-RP09-LC15), no row of a listed tenant may have a clear value
// and no sealed value, and no release before may run (runningReleases). The
// pass must also have started in this database instance (seal_instance: the
// database, the start of its server and the table of the checkpoints), so a
// completed pass that a restore brings, or that ran before a restart of the
// server, does not count until the seal job completes a new pass (security
// review of PR #471, L3). When the clear column is gone, a run before dropped
// it and the check passes.
func checkSeal(ctx context.Context, tx *sql.Tx, c ContractStep, table string) error {
	var there bool
	if err := tx.QueryRowContext(ctx, "SELECT EXISTS (SELECT 1 FROM pg_catalog.pg_attribute a WHERE a.attrelid = pg_catalog.to_regclass($1) AND a.attname = $2 AND a.attnum > 0 AND NOT a.attisdropped)", table, c.From).Scan(&there); err != nil {
		return err
	}
	if !there {
		return nil
	}
	var seals bool
	if err := tx.QueryRowContext(ctx, "SELECT pg_catalog.to_regclass('stego_schema.seals') IS NOT NULL AND pg_catalog.to_regclass('stego_schema.releases') IS NOT NULL").Scan(&seals); err != nil {
		return err
	}
	state := "the seal checkpoint of the change is not there"
	if seals {
		// A checkpoint with no record of the database instance where the seal job saw it counts as not seen here.
		var instance bool
		if err := tx.QueryRowContext(ctx, "SELECT pg_catalog.to_regprocedure('stego_schema.seal_instance()') IS NOT NULL AND EXISTS (SELECT 1 FROM pg_catalog.pg_attribute a WHERE a.attrelid = 'stego_schema.seals'::pg_catalog.regclass AND a.attname = 'armed_in' AND a.attnum > 0 AND NOT a.attisdropped)").Scan(&instance); err != nil {
			return err
		}
		seen := "false"
		if instance {
			seen = "s.armed_in IS NOT DISTINCT FROM stego_schema.seal_instance()"
		}
		var complete, stale, here bool
		err := tx.QueryRowContext(ctx, "SELECT s.completed_at IS NOT NULL, EXISTS (SELECT 1 FROM stego_schema.releases r WHERE r.release COLLATE \"C\" < s.expand COLLATE \"C\" AND r.seen_at + r.every_ms * $2::integer * interval '1 millisecond' > s.pass_started), "+seen+" FROM stego_schema.seals s WHERE s.change_id = $1", c.Change, releaseWindow).Scan(&complete, &stale, &here)
		switch {
		case errors.Is(err, sql.ErrNoRows):
		case err != nil:
			return err
		case !complete:
			state = "the seal job of the controller has not completed a pass over the rows"
		case stale:
			state = "a release before the step ran after the start of the last pass of the seal job, so a sealed value can be older than its clear value"
		case !here:
			state = "the last pass of the seal job did not run in this database instance, as after a restore or a restart of the database server, so a release before can have written a clear value after it"
		default:
			state = ""
		}
	}
	if state != "" {
		return &contractRefusal{text: fmt.Sprintf("the contract step of the schema change %s waits for its seal: %s; run the migration job of the release of the expand step %s and then that release, with its controller, until the seal job completes a pass. When that release was built with a postgres-adapter before 6.21.0, build it again with postgres-adapter 6.21.0 and the runtime v0.173.0 or later and deploy it first, because the first release built with 6.21.0 must not hold the contract step of a seal", c.Change, state, c.Expand), wait: sealWait}
	}
	left, err := rowsLeft(ctx, tx, c)
	if err != nil {
		return err
	}
	if left > 0 {
		return &contractRefusal{text: fmt.Sprintf("the contract step of the schema change %s waits for its seal: rows of the listed tenants with a clear value and no sealed value: %d; run the migration job of the release of the expand step %s and then that release, with its controller, until the seal job completes a pass. The seal job of a runtime before v0.207.0 passes over the active tenants alone and leaves the rows of a retired tenant in clear, so that release needs the runtime v0.207.0 or later, whose seal job passes over each tenant of the tenant list and starts a new pass while a row is in clear. The seal job of code that a postgres-adapter before 6.33.0 generated never reads a row with the zero UUID, so with such a row that release also needs to be built with postgres-adapter 6.33.0 or later. When that release was built with a postgres-adapter before 6.21.0, build it again with postgres-adapter 6.21.0 and the runtime v0.173.0 or later and deploy it first, because the first release built with 6.21.0 must not hold the contract step of a seal", c.Change, left, c.Expand), wait: sealWait}
	}
	return runningReleases(ctx, tx, c)
}

// rowsLeft counts the rows of the table of c whose old column is set and
// whose new column is empty: on an owned table, which has row-level security,
// for each tenant of the tenant list in turn under its tenant setting.
func rowsLeft(ctx context.Context, tx *sql.Tx, c ContractStep) (int64, error) {
	table := quoteIdentifier(c.Schema) + "." + quoteIdentifier(c.Table)
	count := "SELECT pg_catalog.count(*) FROM " + table + " WHERE " + c.Old + " IS NOT NULL AND " + c.New + " IS NULL"
	if c.TenantColumn == "" {
		var n int64
		err := tx.QueryRowContext(ctx, count).Scan(&n)
		return n, err
	}
	rows, err := tx.QueryContext(ctx, "SELECT t.tenant_id FROM "+quoteIdentifier(c.TenantSchema)+".stego_tenants t ORDER BY t.tenant_id COLLATE \"C\"")
	if err != nil {
		return 0, err
	}
	var tenants []string
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			rows.Close()
			return 0, err
		}
		tenants = append(tenants, id)
	}
	rows.Close()
	if err := rows.Err(); err != nil {
		return 0, err
	}
	var total int64
	for _, id := range tenants {
		var n int64
		if _, err := tx.ExecContext(ctx, "SELECT pg_catalog.set_config('app.tenant', $1, true)", id); err != nil {
			return 0, err
		}
		if err := tx.QueryRowContext(ctx, count).Scan(&n); err != nil {
			return 0, err
		}
		total += n
	}
	_, err = tx.ExecContext(ctx, "SELECT pg_catalog.set_config('app.tenant', '', true)")
	return total, err
}

// runningReleases refuses while a process of a release that does not know
// the change reports itself in stego_schema.releases (decision on finding F8
// of the schema-change research, owner, 2026-11-13; ST-SUP-RP09-LC14): a
// release whose last migration sorts before the expand migration of the
// change, with a report younger than releaseWindow of its intervals. It
// refuses when the table is missing, as the expand migration makes it.
func runningReleases(ctx context.Context, tx *sql.Tx, c ContractStep) error {
	var table bool
	if err := tx.QueryRowContext(ctx, "SELECT pg_catalog.to_regclass('stego_schema.releases') IS NOT NULL").Scan(&table); err != nil {
		return err
	}
	if !table {
		return &contractRefusal{text: fmt.Sprintf("the contract step of the schema change %s finds no table stego_schema.releases of the release reports, which the expand migration of the change makes", c.Change), wait: reportsWait}
	}
	rows, err := tx.QueryContext(ctx, "SELECT r.version, pg_catalog.count(*) FROM stego_schema.releases r WHERE r.release COLLATE \"C\" < $1 COLLATE \"C\" AND r.seen_at > pg_catalog.clock_timestamp() - r.every_ms * $2::integer * interval '1 millisecond' GROUP BY r.version ORDER BY r.version COLLATE \"C\"", c.Expand, releaseWindow)
	if err != nil {
		return err
	}
	defer rows.Close()
	var running []string
	for rows.Next() {
		var version string
		var n int64
		if err := rows.Scan(&version, &n); err != nil {
			return err
		}
		if version == "" {
			version = "with no version"
		}
		running = append(running, fmt.Sprintf("%s (%d processes)", version, n))
	}
	if err := rows.Err(); err != nil {
		return err
	}
	if len(running) > 0 {
		// The contract of a drop of an entity drops a table, and every other contract step an old column.
		old := "the old column"
		switch {
		case c.Drop && c.Index != "":
			old = "the search index " + c.Index
		case c.Drop && c.From == "":
			old = "the old table"
		}
		return &contractRefusal{text: fmt.Sprintf("the contract step of the schema change %s waits for the release before to stop: the releases %s run and do not know the migration %s, so they still need %s; stop them, and run the migration job again", c.Change, strings.Join(running, ", "), c.Expand, old), wait: releaseWait}
	}
	return nil
}

// dropAfterFailure drops the invalid index index that a failed build left,
// under the lock timeout of a step, and when the drop fails it runs it again
// after a pause, at most dropAttempts times. An invalid unique index that is
// ready goes on enforcing its key on the writes of the release before, so a
// drop that still fails gives an error that names the index, and the job
// fails with it; it never stays silent (ST-SUP-RC01-OC38).
func dropAfterFailure(ctx context.Context, conn *sql.Conn, index string) error {
	var err error
	for attempt := 1; attempt <= dropAttempts; attempt++ {
		if attempt > 1 {
			if err := pause(ctx, attempt-1); err != nil {
				return err
			}
		}
		if _, err = conn.ExecContext(ctx, "SELECT pg_catalog.set_config('lock_timeout', $1, false)", stepLockTimeout); err == nil {
			if err = dropInvalid(ctx, conn, index); err == nil {
				return nil
			}
		}
	}
	return fmt.Errorf("the failed build left the invalid index %s, and %d drops of it failed, the last with: %v", index, dropAttempts, err)
}

// sessionOf gives one connection of db for a session setting, and the function
// that gives it back: db itself when it is one connection, else a connection of
// its pool.
func sessionOf(ctx context.Context, db Database) (*sql.Conn, func(), error) {
	switch d := db.(type) {
	case *sql.Conn:
		return d, func() {}, nil
	case interface {
		Conn(context.Context) (*sql.Conn, error)
	}:
		conn, err := d.Conn(ctx)
		if err != nil {
			return nil, nil, err
		}
		return conn, func() { _ = conn.Close() }, nil
	}
	return nil, nil, ErrMigrationLedger
}

// dropInvalid drops the index index, outside a transaction, when it is there
// and not valid.
func dropInvalid(ctx context.Context, conn *sql.Conn, index string) error {
	var invalid bool
	if err := conn.QueryRowContext(ctx, "SELECT EXISTS (SELECT 1 FROM pg_catalog.pg_index WHERE indexrelid = pg_catalog.to_regclass($1) AND NOT indisvalid)", index).Scan(&invalid); err != nil {
		return err
	}
	if !invalid {
		return nil
	}
	_, err := conn.ExecContext(ctx, "DROP INDEX CONCURRENTLY IF EXISTS "+index)
	return err
}

// registerGenerated registers the generated migrations in their fixed order.
func registerGenerated() {
	RegisterSQL("001_initial", InitialTables)
	RegisterSQL("100_tenancy_row_security", stegotenancy.RowSecurity)
	RegisterStep("step_0001_organization-description-relax_expand", "CREATE TABLE IF NOT EXISTS stego_schema.releases (\n\tholder text PRIMARY KEY,\n\trelease text NOT NULL,\n\tversion text NOT NULL,\n\tevery_ms integer NOT NULL,\n\tseen_at timestamptz NOT NULL\n);\nCREATE INDEX IF NOT EXISTS releases_seen_at ON stego_schema.releases (seen_at);\nREVOKE ALL ON TABLE stego_schema.releases FROM PUBLIC;\nCREATE OR REPLACE FUNCTION stego_schema.release_beat(text, text, text, integer)\n RETURNS void LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, pg_temp SET lock_timeout = '1s'\n AS $stego_release$BEGIN\n  IF $1 IS NULL OR $2 IS NULL OR $3 IS NULL OR $4 IS NULL OR $1 !~ '^[0-9a-f]{32}$' OR $2 !~ '^[0-9a-z_-]{1,200}$'\n   OR $3 !~ '^[ -~]{0,64}$' OR $4 < 1000 OR $4 > 60000 THEN\n    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'stego release report: an argument is out of range';\n  END IF;\n  INSERT INTO stego_schema.releases AS r (holder, release, version, every_ms, seen_at)\n   VALUES ($1, $2, $3, $4, pg_catalog.clock_timestamp())\n   ON CONFLICT (holder) DO UPDATE SET release = EXCLUDED.release, version = EXCLUDED.version, every_ms = EXCLUDED.every_ms,\n   seen_at = EXCLUDED.seen_at;\nEND$stego_release$;\nCREATE OR REPLACE FUNCTION stego_schema.release_stop(text)\n RETURNS void LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, pg_temp SET lock_timeout = '1s'\n AS $stego_release$DELETE FROM stego_schema.releases r WHERE r.holder = $1$stego_release$;\nREVOKE ALL ON FUNCTION stego_schema.release_beat(text, text, text, integer) FROM PUBLIC;\nREVOKE ALL ON FUNCTION stego_schema.release_stop(text) FROM PUBLIC;\nGRANT USAGE ON SCHEMA stego_schema TO \"user_management_runtime\";\nGRANT EXECUTE ON FUNCTION stego_schema.release_beat(text, text, text, integer) TO \"user_management_runtime\";\nGRANT EXECUTE ON FUNCTION stego_schema.release_stop(text) TO \"user_management_runtime\";\n")
}
